    padding: 0.75rem;
    background: #f8f9fa;
    border-radius: 4px;
}

::deep .sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

::deep .sort-control select {
    padding: 0.4rem;
    border: 1px solid #ccc;
    border-radius: 4px;
}

::deep .showing-label {
    font-size: 0.9rem;
    color: #666;
}

::deep .product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

::deep .product-card {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    cursor: pointer;
    transition: box-shadow 0.2s;
}

::deep .product-card:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.12);
}

::deep .product-image {
    height: 150px;
    background: #f0f0f0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 0.85rem;
    text-align: center;
    padding: 1rem;
}

::deep .product-info {
    padding: 0.75rem;
}

::deep .product-name {
    margin: 0 0 0.25rem;
    font-size: 1rem;
}

::deep .product-price {
    margin: 0 0 0.25rem;
    font-weight: bold;
    color: #2a7d2a;
}

::deep .product-rating {
    color: #f5a623;
    margin-bottom: 0.5rem;
}

::deep .badge-out-of-stock {
    display: inline-block;
    padding: 0.2rem 0.5rem;
    background: #dc3545;
    color: white;
    border-radius: 4px;
    font-size: 0.75rem;
    margin-bottom: 0.5rem;
}

::deep .btn-add-to-cart {
    width: 100%;
    padding: 0.5rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: white;
    cursor: pointer;
}

::deep .btn-add-to-cart:disabled {
    background: #ccc;
    cursor: not-allowed;
}

::deep .pagination {
    display: flex;
    justify-content: center;
    gap: 0.25rem;
    margin-top: 1.5rem;
    padding: 1rem 0;
}

::deep .btn-page {
    padding: 0.4rem 0.75rem;
    border: 1px solid #dee2e6;
    background: white;
    border-radius: 4px;
    cursor: pointer;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

::deep .btn-page:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

::deep .catalog-loading,
::deep .catalog-error,
::deep .catalog-empty {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
    font-size: 1.1rem;
    color: #666;
}

::deep .catalog-error {
    color: #dc3545;
}
"}

