@namespace sv_525e661f9ff740d3983d475284740275.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div class="product-info">
        <h4 class="product-name">@Product.Name</h4>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <div class="product-rating" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">
            @GetStarDisplay()
        </div>
        @if (!Product.InStock)
        {
            <span class="badge-out-of-stock">Out of Stock</span>
        }
        <button class="btn-add-to-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private string GetStarDisplay()
    {
        int filled = (int)Math.Round(Product.Rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }
}

@namespace sv_525e661f9ff740d3983d475284740275.Components.Pages.Catalog

<aside class="catalog-filters">
    <h3>Filters</h3>

    <div class="filter-section">
        <h4>Categories</h4>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    @category
                </label>
            }
        }
    </div>

    <div class="filter-section">
        <h4>Price Range</h4>
        <label>
            Min:
            <input type="number" min="0" step="0.01"
                   value="@_minPrice"
                   @onchange="@(e => _minPrice = ParseDecimal(e.Value))" />
        </label>
        <label>
            Max:
            <input type="number" min="0" step="0.01"
                   value="@_maxPrice"
                   @onchange="@(e => _maxPrice = ParseDecimal(e.Value))" />
        </label>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@_inStockOnly"
                   @onchange="@(e => _inStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
    </div>
</aside>

@code {
    [Parameter]
    public List<string>? Categories { get; set; }

    [Parameter]
    public EventCallback<ProductFilter> OnFiltersApplied { get; set; }

    [Parameter]
    public EventCallback OnFiltersCleared { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!isChecked)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: _minPrice,
            MaxPrice: _maxPrice,
            InStockOnly: _inStockOnly
        );
        await OnFiltersApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFiltersCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_525e661f9ff740d3983d475284740275.Components.Pages.Catalog

<section class="catalog-products">
    @if (IsLoading)
    {
        <div class="catalog-loading">
            <p>Loading products...</p>
        </div>
    }
    else if (ErrorMessage is not null)
    {
        <div class="catalog-error">
            <p>@ErrorMessage</p>
        </div>
    }
    else if (Result is null || Result.Items.Count == 0)
    {
        <div class="catalog-empty">
            <p>No products found matching your criteria.</p>
        </div>
    }
    else
    {
        <div class="catalog-toolbar">
            <div class="sort-control">
                <label for="sort-select">Sort by:</label>
                <select id="sort-select" value="@SortBy" @onchange="HandleSortChange">
                    <option value="price_asc">Price: Low to High</option>
                    <option value="price_desc">Price: High to Low</option>
                    <option value="name_asc">Name: A-Z</option>
                    <option value="rating_desc">Rating: Highest</option>
                </select>
            </div>
            <span class="showing-label">
                Showing @(StartItem)–@(EndItem) of @Result.TotalCount products
            </span>
        </div>

        <div class="product-grid">
            @foreach (var product in Result.Items)
            {
                <ProductCard Product="@product"
                             OnSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />
            }
        </div>

        <nav class="pagination" aria-label="Product pagination">
            <button class="btn-page" disabled="@(Result.Page <= 1)" @onclick="() => ChangePage(Result.Page - 1)">
                Previous
            </button>
            @for (int i = 1; i <= TotalPages; i++)
            {
                var pageNum = i;
                <button class="btn-page @(pageNum == Result.Page ? "active" : "")"
                        @onclick="() => ChangePage(pageNum)">
                    @pageNum
                </button>
            }
            <button class="btn-page" disabled="@(Result.Page >= TotalPages)" @onclick="() => ChangePage(Result.Page + 1)">
                Next
            </button>
        </nav>
    }
</section>

@code {
    [Parameter]
    public PagedResult<Product>? Result { get; set; }

    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public bool IsLoading { get; set; }

    [Parameter]
    public string? ErrorMessage { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int TotalPages => Result is null || Result.PageSize == 0
        ? 0
        : (int)Math.Ceiling((double)Result.TotalCount / Result.PageSize);

    private int StartItem => Result is null ? 0 : (Result.Page - 1) * Result.PageSize + 1;

    private int EndItem => Result is null ? 0 : Math.Min(Result.Page * Result.PageSize, Result.TotalCount);

    private async Task HandleSortChange(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }

    private async Task ChangePage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }
}

